/** MIT; own U017 photographed Type-C/whiteGrove variant,hidden internals inferred. */
import * as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{solid,rectangleRing}from'./geometry.js';import{spec}from'./dimensions.js';
export function addConnectors(host,frame){const white=materials.plastic(0xe5e5da,{roughness:.7}),black=materials.plastic(0x161b1b,{roughness:.7}),metal=materials.metal(0xb3b6aa,{roughness:.42}),gold=materials.metal(0xba9d5d,{roughness:.45}),box=(p,s,q,n,m=white)=>mesh(p,new THREE.BoxGeometry(...s),m,q,'U017 '+n);
 const g=new THREE.Group();g.position.fromArray(spec.grove.position);g.quaternion.copy(portQuaternion('bottom'));g.name='U017 actual rear white four-pin receiving assembly';frame.add(g);const grove={frame:g,walls:[],contacts:[],returns:[],feet:[],tails:[]};for(const sign of[-1,1]){grove.walls.push(box(g,[.7,7.6,3.1],[sign*5.05,-3.8,0],'Grove real sidewall'));grove.walls.push(box(g,[.6,1.4,.45],[sign*4.15,-1.8,1.325],'Grove real mouth latch'));}grove.floor=box(g,[9.4,7.6,.6],[0,-3.8,-1.25],'Grove real receiving floor');grove.back=box(g,[9.4,.65,2.5],[0,-7.275,.3],'Grove actual deep stop');grove.bridge=box(g,[4.5,2,.5],[0,-5,.9],'Grove physical rearPCB clearance bridge');for(let i=0;i<4;i++){const x=(i-1.5)*2;grove.contacts.push(box(g,[.42,6.3,.42],[x,-4.35,.3],'Grove retained contact '+(i+1),metal));grove.returns.push(box(g,[.42,.42,1.4],[x,-7.4,.8],'Grove actual metal bend '+(i+1),metal));grove.feet.push(box(g,[.42,1.5,.42],[x,-8,.94],'Grove actual solder foot '+(i+1),metal));grove.tails.push(box(g,[.42,.42,1.4],[x,-8.5,1.55],'Grove actual vertical throughPCB tail '+(i+1),metal));}grove.port=host.add(new Port({id:'grove',label:'Original U017 white HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10.8,1,3.1],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.3],order:i=>i+1},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',scope:'Current/immutable original documentaryG13/G4/5V/GND only;no electrical routing/I2C;quickcardG12 conflict recorded'}}),frame);
 const v=new THREE.Group();v.position.fromArray(spec.usb.position);v.quaternion.copy(FACE.bottom);v.name='U017 actual own-photo Type-C hollow receiver';frame.add(v);const usb={frame:v,contacts:[],returns:[],tails:[],feet:[]};usb.shield=solid(v,rectangleRing(9,3.2,1.6,8.4,2.6,1.3),7.2,[0,0,-7.2],metal,'U017 real hollow USB-C metal shield');usb.stop=box(v,[8.2,2.4,.55],[0,0,-6.925],'USB-C retained dielectric stop',black);usb.tongue=box(v,[6.7,.65,5.4],[0,0,-4.1],'USB-C actual dielectric tongue',black);usb.seat=box(v,[8, .3,1.6],[0,-1.25,-8],'USB-C actual dielectric carrier seats PCB',black);for(const side of[-1,1])for(let i=0;i<12;i++){const x=(i-5.5)*.5;usb.contacts.push(box(v,[.23,.08,4.3],[x,side*.365,-4.35],'USB-C standard-style retained contact,hidden variant inferred',gold));usb.returns.push(box(v,[.16,2.1,.4],[x+side*.08,-.45,-6.5],'USB-C retained internal bend',metal));usb.tails.push(box(v,[.16,.1,2],[x+side*.08,-1.35,-7.65],'USB-C actual surface solder tail',metal));}for(const x of[-3.7,3.7])usb.feet.push(box(v,[1,.3,4.4],[x,-1.25,-6.6],'USB-C actual shield retention to PCB',metal));usb.port=host.add(new Port({id:'usb',label:'Original U017 photographed USB-C mechanical port',connector:'usb-c',position:spec.usb.position,quaternion:portQuaternion('bottom'),hitSize:[9,1,3.2],meta:{role:'visual-connector',variant:'Own03 Type-C appearance;old schematicUSB_Micro conflict retained',scope:'Physical receiver only;hidden contact detail/count inferred,no USB/UART/electrical/power/firmware'}}),frame);return{grove,usb};}
